function supportNumberKeys(value){const normalised=normaliseCvText(value).toLowerCase().replace(/[–—−]/g,'-');const matches=normalised.match(/\b\d[\d,]*(?:\.\d+)?\b/g)||[];return new Set(matches.map(number=>number.replace(/,/g,'')).filter(Boolean));}
function canonicalEvidenceText(value){return normaliseCvText(value).toLowerCase().replace(/&/g,' and ').replace(/[–—−]/g,'-').replace(/\bmicrosoft\b/g,'ms').replace(/\bpower point\b/g,'powerpoint').replace(/\bms-office\b/g,'ms office').replace(/[^a-z0-9+#.\-]+/g,' ').replace(/\s+/g,' ').trim();}
