async function repairCvIndependently(env,originalText,targetRole=''){const prompt=`You are repairing an early-career professional CV independently of any job description.\n\nUse only facts explicitly contained in the ORIGINAL CV. Do not infer or invent any skill, qualification, employer, role, responsibility, achievement, tool, certification, number, result, date, project, or claim.\n\nProduce a truthful one-page CV for the locked FIIB format:\n- one column, Arial, approved section order;\n- Career Summary, Education, Experience, Projects, Positions of Responsibility, Skills, Tools, Certifications;\n- Career Summary must be one concise paragraph, not bullets or separate mini-paragraphs;\n- build the summary in the logic NOW → CLAIM → EVIDENCE/IMPACT → ASPIRATION;\n- NOW: state the current academic/professional status exactly as supported by the source;\n- CLAIM: state one or two credible capabilities or areas of strength. Treat these as claims, not as evidence;\n- EVIDENCE/IMPACT: support the claim with a specific action, project, internship exposure, work responsibility, or achievement from the source. Include a result, change, contribution, or business consequence only when the source explicitly supports it. Never describe an activity alone as impact;\n- ASPIRATION: if TARGET ROLE OR ROLE FAMILY below is supplied, use it to state a credible next direction. If it is blank, use only a career direction explicitly supported by the source; if none exists, do not invent one and end the summary after evidence/impact;\n- no more than eight experience bullets across the whole CV;\n- no more than three projects and two positions of responsibility;\n- concise experience bullets using Result–Action–Context only when a genuine result exists;\n- when no result exists, use Action–Context and do not manufacture a result;\n- preserve every employer, role, qualification, and material verified achievement;\n- condense repetition and weak wording to remain within one page;\n- never use a JD or introduce role-targeting language unsupported by the source.\n\nBefore returning the CV, perform a final ATS clean-up pass yourself:\n- Use the candidate name as plain text on one line and a single clean contact line.\n- Standardise date punctuation and style. Prefer Month YYYY – Month YYYY when both months are explicitly present. If only years are present, keep years only. Replace the word "to" with an en dash. Do not invent start/end months.\n- For a current or pursuing qualification, use "Present" or "Expected YYYY" only when that meaning/year is explicitly supported by the source. Do not invent months.\n- Put each role in a compact ATS-readable role line. Keep title, employer and location on the same role line when all are explicitly present. The application will append the dates to that line.\n- Start experience bullets with strong action verbs where this can be done without changing the underlying claim.\n- Use a dedicated Skills list made of exact hard-skill nouns that are explicitly evidenced in the source. Do not add target-role keywords unless they are already supported by the CV.\n- Use standard tool/certification naming only when the source supports the tool or issuer. Add issuer/date only when explicitly present.\n- Never manufacture a percentage, number, result, certification date, start month, end month, employer, location, skill or keyword.\n- Do not leave advice telling the learner to make a formatting or wording change that you could safely make yourself.\n\nIn repair_summary, list only changes you actually applied.\nIn unresolved_items, list only facts that would improve the final CV but cannot be supplied truthfully from the source, such as an absent certification date, absent location, or missing measurable result. Do not list formatting or wording tasks you have already fixed.\nIn check_before_using, give at most one short sentence reminding the learner to verify factual accuracy. Do not repeat ATS advice already applied.\n\nReturn structured fields only. The application controls fonts, margins, spacing, headings, and the final RTF document.\n\nTARGET ROLE OR ROLE FAMILY (may be blank):\n${targetRole}\n\nORIGINAL CV:\n${originalText}`;const revisedCvSchema={type:'object',properties:{name:{type:'string'},contact:{type:'string'},career_summary:{type:'string'},education:{type:'array',items:{type:'string'}},experience:{type:'array',items:{type:'object',properties:{role_line:{type:'string'},dates:{type:'string'},bullets:{type:'array',items:{type:'string'}}},required:['role_line','dates','bullets']}},projects:{type:'array',items:{type:'object',properties:{label:{type:'string'},detail:{type:'string'}},required:['label','detail']}},positions_of_responsibility:{type:'array',items:{type:'object',properties:{label:{type:'string'},detail:{type:'string'}},required:['label','detail']}},skills:{type:'array',items:{type:'string'}},tools:{type:'array',items:{type:'string'}},certifications:{type:'array',items:{type:'string'}}},required:['name','contact','career_summary','education','experience','projects','positions_of_responsibility','skills','tools','certifications']};const schema={type:'object',properties:{revised_cv:revisedCvSchema,repair_summary:{type:'array',items:{type:'string'}},unresolved_items:{type:'array',items:{type:'string'}},check_before_using:{type:'string'}},required:['revised_cv','repair_summary','unresolved_items','check_before_using']};let response=null,lastRepairError=null;for(let attempt=0;attempt<2;attempt++){const controller=new AbortController();const timeoutId=setTimeout(()=>controller.abort(),45000);try{response=await fetch('https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent',{method:'POST',headers:{'content-type':'application/json','x-goog-api-key':env.GEMINI_API_KEY},body:JSON.stringify({contents:[{parts:[{text:prompt+(attempt?'\n\nPrevious repair attempt did not complete. Return the same required JSON structure now, concisely and without adding unsupported facts.':'')}]}],generationConfig:{responseMimeType:'application/json',responseSchema:schema,temperature:0}}),signal:controller.signal});clearTimeout(timeoutId);if(response.ok)break;lastRepairError=new Error(`CV repair service error (${response.status}).`);}catch(error){clearTimeout(timeoutId);lastRepairError=error&&error.name==='AbortError'?new Error('The CV repair service took too long to respond.'):error;}}if(!response||!response.ok)throw new Error(`${lastRepairError?.message||'The CV repair service did not respond.'} Please try Repair CV again.`);const data=await response.json();const text=data?.candidates?.[0]?.content?.parts?.map(part=>part.text||'').join('')||'';const result=JSON.parse(text.replace(/^```json\s*/i,'').replace(/```\s*$/,'').replace(/,\s*([}\]])/g,'$1').trim());const cv=finaliseCvStructure(result.revised_cv);const bulletCount=(cv.experience||[]).reduce((sum,item)=>sum+(Array.isArray(item.bullets)?item.bullets.length:0),0);if(bulletCount>8||(cv.projects||[]).length>3||(cv.positions_of_responsibility||[]).length>2)throw new Error('The repaired CV exceeded the approved one-page content limits. Please try again.');const revisedText=buildLockedCvText(cv);if(revisedText.split(/\s+/).filter(Boolean).length>600)throw new Error('The repaired CV is still too long for the approved one-page format. Please shorten the source CV and try again.');validateRewrittenCv(originalText,revisedText,cv);return{revised_cv:cv,revised_text:revisedText,repair_summary:(result.repair_summary||[]).map(String).filter(Boolean).slice(0,8),unresolved_items:(result.unresolved_items||[]).map(String).filter(Boolean).slice(0,8),check_before_using:String(result.check_before_using||'').trim()};}
function normaliseDateDisplay(value){return String(value||'').replace(/\bto\b/gi,'–').replace(/\s*[-–—]\s*/g,' – ').replace(/\s+/g,' ').trim();}
function cleanHeaderText(value){return String(value||'').replace(/\s+/g,' ').trim();}
function finaliseCvStructure(cv){const value=cv&&typeof cv==='object'?JSON.parse(JSON.stringify(cv)):{};value.name=cleanHeaderText(value.name);value.contact=cleanHeaderText(value.contact).replace(/\s*[•·]\s*/g,' | ').replace(/\s*\|\s*/g,' | ');value.education=(Array.isArray(value.education)?value.education:[]).map(item=>normaliseDateDisplay(item)).filter(Boolean);value.experience=(Array.isArray(value.experience)?value.experience:[]).map(item=>({role_line:cleanHeaderText(item?.role_line),dates:normaliseDateDisplay(item?.dates),bullets:(Array.isArray(item?.bullets)?item.bullets:[]).map(b=>cleanHeaderText(b)).filter(Boolean)}));value.projects=(Array.isArray(value.projects)?value.projects:[]).map(item=>({label:cleanHeaderText(item?.label),detail:cleanHeaderText(item?.detail)})).filter(item=>item.label||item.detail);value.positions_of_responsibility=(Array.isArray(value.positions_of_responsibility)?value.positions_of_responsibility:[]).map(item=>({label:cleanHeaderText(item?.label),detail:cleanHeaderText(item?.detail)})).filter(item=>item.label||item.detail);value.skills=(Array.isArray(value.skills)?value.skills:[]).map(cleanHeaderText).filter(Boolean);value.tools=(Array.isArray(value.tools)?value.tools:[]).map(cleanHeaderText).filter(Boolean);value.certifications=(Array.isArray(value.certifications)?value.certifications:[]).map(item=>normaliseDateDisplay(item)).filter(Boolean);return value;}
function buildLockedCvText(cv){const value=cv&&typeof cv==='object'?cv:{};const lines=[];const add=item=>{const text=String(item||'').replace(/\r?\n/g,' ').trim();if(text)lines.push(text);};const section=name=>lines.push(name);const bullets=items=>(Array.isArray(items)?items:[]).forEach(item=>{const text=String(item||'').replace(/\r?\n/g,' ').trim();if(text)lines.push(`- ${text}`);});add(value.name);add(value.contact);section('CAREER SUMMARY');add(value.career_summary);section('EDUCATION');(value.education||[]).forEach(add);section('EXPERIENCE');(value.experience||[]).forEach(item=>{const roleLine=String(item.role_line||'').trim();const dates=normaliseDateDisplay(item.dates);add(roleLine&&dates?`${roleLine} | ${dates}`:(roleLine||dates));bullets(item.bullets);});section('PROJECTS');(value.projects||[]).forEach(item=>{const label=String(item.label||'').replace(/:$/,'').trim();const detail=String(item.detail||'').trim();if(label&&detail)lines.push(`- ${label}: ${detail}`);});section('POSITIONS OF RESPONSIBILITY');(value.positions_of_responsibility||[]).forEach(item=>{const label=String(item.label||'').replace(/:$/,'').trim();const detail=String(item.detail||'').trim();if(label&&detail)lines.push(`- ${label}: ${detail}`);});section('SKILLS');add((value.skills||[]).join(' | '));section('TOOLS');add((value.tools||[]).join(' | '));section('CERTIFICATIONS');add((value.certifications||[]).join(' | '));return lines.join('\n');}
